package com.procurement.purchaseorder.mapper;import com.procurement.purchaseorder.dto.response.*;import com.procurement.purchaseorder.entity.*;import org.springframework.stereotype.Component;@Component public class PurchaseOrderMapper{public PurchaseOrderResponse po(PurchaseOrder e){return new PurchaseOrderResponse(e.getId(),e.getPoNumber(),e.getQuotationComparison().getId(),e.getVendorQuotation().getId(),e.getVendor().getId(),e.getVendor().getVendorName(),e.getPurchaseRequest().getId(),e.getPurchaseRequest().getRequestNumber(),e.getOrderDate(),e.getExpectedDeliveryDate(),e.getCurrency(),e.getSubtotal(),e.getDiscountAmount(),e.getTaxAmount(),e.getShippingCharges(),e.getOtherCharges(),e.getGrandTotal(),e.getPaymentTerms(),e.getDeliveryAddress(),e.getBillingAddress(),e.getStatus(),e.getRemarks());}public PurchaseOrderLineResponse line(PurchaseOrderLine e){return new PurchaseOrderLineResponse(e.getId(),e.getPurchaseOrder().getId(),e.getProduct().getId(),e.getProduct().getProductName(),e.getQuantityOrdered(),e.getQuantityReceived(),e.getUnitPrice(),e.getDiscountPercentage(),e.getTaxPercentage(),e.getLineAmount(),e.getRemarks());}public PurchaseOrderAttachmentResponse attachment(PurchaseOrderAttachment e){return new PurchaseOrderAttachmentResponse(e.getId(),e.getPurchaseOrder().getId(),e.getFileName(),e.getFilePath(),e.getFileType(),e.getUploadedAt());}public PurchaseOrderHistoryResponse history(PurchaseOrderHistory e){return new PurchaseOrderHistoryResponse(e.getId(),e.getPurchaseOrder().getId(),e.getAction(),e.getOldStatus(),e.getNewStatus(),e.getRemarks(),e.getPerformedAt());}}
